class Solution:
    def occurrencesOfElement(self, nums, queries, x):
        occ = [i for i, v in enumerate(nums) if v == x]
        return [occ[q - 1] if q <= len(occ) else -1 for q in queries]

c.cpp:
class Solution {
public:
    vector<int> occurrencesOfElement(vector<int>& nums, vector<int>& queries, int x) {
        vector<int> occ;
        for (int i = 0; i < (int)nums.size(); i++)
            if (nums[i] == x) occ.push_back(i);
        vector<int> res;
        res.reserve(queries.size());
        for (int q : queries)
            res.push_back(q <= (int)occ.size() ? occ[q - 1] : -1);
        return res;
    }
};

c.java:
class Solution {
    public int[] occurrencesOfElement(int[] nums, int[] queries, int x) {
        List<Integer> occ = new ArrayList<>();
        for (int i = 0; i < nums.length; i++)
            if (nums[i] == x) occ.add(i);
        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int q = queries[i];
            res[i] = q <= occ.size() ? occ.get(q - 1) : -1;
        }
        return res;
    }
}

